GUIDE_PATHS = ('/oppaat/kellojen-siirto-2026/', '/oppaat/talvirenkaat-2026/', '/oppaat/palovaroittimen-tarkistus/', '/oppaat/liputuspaivat-2026/', '/oppaat/influenssarokotus-2026/', '/oppaat/koronarokotus-2026/')


def guides(now) -> tuple[dict, ...]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('Aware current time required')
    expired = now.astimezone(ZoneInfo('Europe/Helsinki')).date() >= datetime(2026, 10, 26).date()
    clock_answer = ('Suomessa kelloja siirrettiin sunnuntaina 25. lokakuuta 2026 aamulla kello 04.00 takaisin kello 03.00. Tämä sivu käsittelee vuoden 2026 syksyn siirtoa, ei seuraavaa kellonsiirtoa.' if expired else
                    'Suomessa kelloja siirretään sunnuntaina 25. lokakuuta 2026 aamulla kello 04.00 takaisin kello 03.00. Yö pitenee yhdellä tunnilla.')
    return (
        dict(path=GUIDE_PATHS[0], title='Kellojen siirto 2026: kellot siirretään taaksepäin su 25.10. kello 04 → 03',
             description='Milloin kelloja siirretään 2026? Normaaliaikaan siirrytään sunnuntaina 25.10.2026 kello 04 → 03, tunti taaksepäin. Lisäksi kevään 2027 siirto ja muistilista laitteille.',
             answer=clock_answer, source=CLOCK_SOURCE, source_label='Finlex: kesäaika-asetus 753/2001, 1 ja 3 §',
             sections=(
                 ('Miksi juuri 25. lokakuuta?', '<p>Asetuksen mukaan normaaliaikaan palataan lokakuun viimeisenä sunnuntaina kello neljä, jolloin aikaa siirretään tunti taaksepäin. Vuoden 2026 kalenterissa viimeinen sunnuntai on 25. lokakuuta. Päivä on laskettu tästä säännöstä.</p>'),
                 ('Muistilista ennen siirtoyötä', '<ol><li>Käy läpi käyttämäsi kellot: puhelin, herätyskello, rannekello, auton kello ja kodin ajastimet. Selvitä kunkin laitteen ohjeesta, vaihtuuko aika automaattisesti.</li><li>Jos laite käyttää automaattista aikaa, tarkista myös aikavyöhyke. Älä tee lisäksi käsin tunnin siirtoa varmistamatta laitteen toimintaa.</li><li>Kirjoita käsin siirrettävien kellojen muistilistaan suunta: neljästä kolmeen, ei neljästä viiteen.</li><li>Tarkista seuraavan aamun tärkeä herätys laitteen näyttämästä ajasta. Pelkkä edellisen illan kellon katsominen ei varmista ajastimen asetuksia.</li></ol>'),
                 ('Yömatka tai sovittu tapaaminen?', '<p>Takaisin siirretty tunti tarkoittaa, että paikallinen kellonaika välillä 03.00–03.59 esiintyy siirtoyönä kahdesti. Jos sovit tapaamisen tähän tuntiin, täsmennä, tarkoitatko ensimmäistä vai jälkimmäistä kertaa. Matkalla tarkista aika lipusta ja liikennöitsijältä: tämä opas ei ratkaise yksittäisen vuoron aikataulua.</p>'),
                 ('Esimerkki: kaksi kelloa ja yksi herätys', '<p>Jos puhelin käyttää automaattista aikaa mutta keittiön kello asetetaan käsin, käsittele ne erillisinä tehtävinä. Selvitä ensin puhelimen asetus ja tee käsin vain keittiön kellon vaatima muutos. Aamulla vertaa näyttöjä ja tarkista herätys. Näin sama tunti ei tule vähennetyksi kahdesti samasta laitteesta. Muistilistan tarkoitus on ehkäistä oma asetusvirhe, ei luvata laitteiden automatiikan toimivuutta.</p>'),
                 ('Eteen vai taakse? Muistisääntö', '<p>Syksyllä kelloja siirretään <strong>tunti taaksepäin</strong>, keväällä tunti eteenpäin. Suomessa siirrytään syksyllä kesäajasta normaaliaikaan eli talviaikaan. Muistisääntö: syksyllä saat tunnin lisää unta, keväällä menetät tunnin.</p>'),
                 ('Seuraava kellonsiirto: kevät 2027', '<p>Asetuksen mukaan kesäaika alkaa maaliskuun viimeisenä sunnuntaina kello kolme, jolloin kelloa siirretään tunti eteenpäin. Vuonna 2027 se on <strong>sunnuntai 28. maaliskuuta kello 03 → 04</strong>. Päivä on laskettu samasta säännöstä vuoden 2027 kalenterista.</p>'),
                 ('Mitä tästä ei voi päätellä?', '<p>Suomen siirtohetki ei ole yleispätevä ohje kaikkien maiden kelloille. Myöskään automaattista kellonsiirtoa ei voi luvata jokaiselle laitteelle. Asetus kertoo ajan vaihtumisesta; laitteen valmistajan ohje kertoo, miten juuri sinun kellosi asetetaan.</p>')),
             related=(('/oppaat/talvirenkaat-2026/', 'Talvirenkaat 2026: milloin ne pitää vaihtaa?'), ('/oppaat/palovaroittimen-tarkistus/', 'Palovaroittimen tarkistus pimeän kauden alussa'), ('/oppaat/liputuspaivat-2026/', 'Liputuspäivät loppuvuonna 2026'), ('/oppaat/#oppaat-junamatka-title', 'Junamatkan aikataulut ja lähtöpaikat'), ('/oppaat/#oppaat-sahkokatko-title', 'Varautuminen sähkökatkoon'))),
        dict(path=GUIDE_PATHS[1], title='Talvirenkaat 2026: milloin ne pitää vaihtaa?',
             description='Talvirengaskausi 1.11.–31.3. on keliperusteinen. Erota 3 mm:n vähimmäisura ja 5 mm:n suositus ja tarkista renkaat ennen vaihtoa.',
             answer='Henkilöautossa, jonka kokonaismassa on enintään 3,5 tonnia, sekä pakettiautossa on käytettävä talvirenkaita 1. marraskuuta–31. maaliskuuta, jos sää tai keli sitä edellyttää. Talvirenkaiden pääurien vähimmäissyvyys on 3 mm; vaikeissa lumi- tai loskaoloissa Traficom suosittelee vähintään 5 mm.',
             source=TYRES_SOURCE, source_label='Traficom: auton kesä- ja talvirenkaat',
             sections=(
                 ('Vaihtopäätös: kolme asiaa samassa järjestyksessä', '<ol><li>Tarkista oman matkasi ajankohta ja reitti. Marraskuun alku ei yksin kerro, onko tiellä talvikeli.</li><li>Katso reitin ajokeli ja säävaroitukset alkuperäisistä palveluista. Arvioi myös paluumatka, älä vain lähtöpaikan tilannetta.</li><li>Tarkista vaihtoon tulevien renkaiden kunto ja merkinnät ennen ajan varaamista. Huonokuntoisen rengassarjan vaihtaminen alle ei ratkaise pito-ongelmaa.</li></ol><p>Ohje on henkilö- ja pakettiautoilijan tarkistuslista, ei keliennuste. Muiden ajoneuvoluokkien ja perävaunujen vaatimukset tarkistat Traficomin sivulta.</p>'),
                 ('3 mm vai 5 mm – mitä ero tarkoittaa?', '<p>Kolme millimetriä on tässä käsiteltyjen talvirenkaiden lakisääteinen pääurien vähimmäissyvyys. Viisi millimetriä on Traficomin suositus vaikeisiin lumi- ja loskaoloihin, ei sama lakiraja. Älä siis tulkitse juuri rajan täyttävää rengasta lupaukseksi riittävästä pidosta kaikissa oloissa.</p>'),
                 ('Rengassarjan tarkistuslista', '<ul><li>Mittaa pääurien syvyys ja kirjaa tulos rengaskohtaisesti. Älä arvioi koko sarjaa vain yhden renkaan perusteella.</li><li>Tarkista nastattoman talvirenkaan lumipitomerkintä: se on ollut henkilö- ja pakettiautoissa pakollinen 1.12.2024 alkaen. Traficomin sivulla on merkinnän kuva; tämä opas ei kopioi sitä.</li><li>Vertaa rengaskokoa auton rekisteritietoihin. Tarkista paineet auton ohjekirjan ja kuormituksen mukaan.</li><li>Jos käytät nastarenkaita, kaikkien renkaiden tulee olla nastoitettuja. Älä kokoa sarjaa sattumanvaraisesti eri tyypeistä.</li></ul>'),
                 ('Kaksi tavallista väärinkäsitystä', '<p>Talvirenkaita ei vaadita automaattisesti jokaisena marraskuun päivänä: sää- tai keliehto kuuluu sääntöön. Nastarenkaiden käyttöaika ei myöskään ole ehdoton kalenteriraja: Traficomin mukaan niitä saa käyttää 1.11.–31.3. ja muulloinkin olosuhteiden vaatiessa. Renkaan valinta ja nopeus on silti sovitettava matkalle, eikä tämä sivu arvioi yksittäisen tien turvallisuutta.</p>')),
             related=(('/oppaat/kellojen-siirto-2026/', 'Kellojen siirto 25. lokakuuta 2026'), ('/oppaat/#oppaat-ajokeli-title', 'Ajokeli ja tiesää reitillä'), ('/oppaat/#oppaat-saavaroitukset-title', 'Säävaroituksen alue ja voimassaolo'), ('/oppaat/#oppaat-heijastin-title', 'Näkyminen pimeässä'))),
        dict(path=GUIDE_PATHS[2], title='Palovaroittimen tarkistus: testinappi ja uusimisajankohta',
             description='Mitä palovaroittimen testinappi kertoo ja mitä ei? Käytännön tarkistuslista paristolle, hälytysäänelle ja valmistajan uusimismerkinnälle.',
             answer='Palovaroittimen testinappi tarkistaa pariston ja hälytysäänen toiminnan, ei kykyä havaita savua. Tarkista siksi myös valmistajan ilmoittama uusimisajankohta, joka löytyy Tukesin mukaan yleensä laitteen pohjasta.',
             source=ALARM_SOURCE, source_label='Tukes: palovaroittimien vaatimukset ja kunnossapito',
             sections=(
                 ('Tarkista kaksi eri asiaa, älä vain piippausta', '<p>Ääni testinapista ja jäljellä oleva käyttöikä vastaavat eri kysymyksiin. Toimiva hälytysääni ei todista savuherkkyyttä eikä kumoa valmistajan uusimismerkintää. Tukes neuvoo uusimaan varoittimen 5–10 vuoden välein, mutta oman laitteen ajankohta tarkistetaan sen merkinnästä. Yleinen vaihtoväli ei korvaa laitekohtaista tietoa.</p>'),
                 ('Käytännön tarkistuslista', '<ol><li>Etsi laitteen käyttöohje. Tarkista, miten sen testinappia käytetään ja millaisia ilmoitusääniä malli antaa.</li><li>Kokeile testinappia ohjeen mukaan. Merkitse muistiin, kuuluiko hälytysääni; älä kirjaa tämän perusteella savuherkkyyttä testatuksi.</li><li>Tarkista valmistajan uusimisajankohta laitteen merkinnästä. Kirjaa päivämäärä tai merkinnän täsmällinen sisältö, jotta siihen voi palata myöhemmin.</li><li>Selvitä virtalähteen tyyppi ohjeesta. Vaihdettava paristo ja laitteen käyttöiän kestävä, ei-vaihdettava virtalähde eivät ole sama asia.</li><li>Jos laite ei toimi tai käyttöikä on päättynyt, ilmoita kunnossapidon tarpeesta rakennuksen omistajalle. Säilytä mallin ja merkinnän tiedot ilmoitusta varten.</li></ol>'),
                 ('Piippaus, paristo vai koko laite?', '<p>Tukesin mukaan vaihdettavan pariston vaihtotarve ilmoitetaan lyhyellä piippauksella. Käyttöiän kestävää virtalähdettä ei voi vaihtaa. Selvitä oman mallisi ilmoitukset käyttöohjeesta sen sijaan, että tulkitsisit kaikki äänet samaksi viaksi. Vikaantunut tai käyttöikänsä päähän tullut varoitin on uusittava.</p>'),
                 ('Mitä ilmoitukseen kannattaa kirjoittaa?', '<p>Tee kunnossapitoilmoituksesta konkreettinen: kerro, mikä varoitin on kyseessä, missä se sijaitsee, mitä testinapista tapahtui ja mitä uusimismerkintä sanoo. Erota oma havainto päätelmästä. Esimerkiksi äänen puuttuminen testissä on havainto; savun havaitsemiskykyä et ole tällä kokeella mitannut. Tietojen kokoaminen auttaa välttämään tilanteen, jossa pelkkä pariston vaihto kuitataan koko laitteen käyttöiän tarkistukseksi.</p>'),
                 ('Vastuu ja tarkistuksen rajat', '<p>Vuoden 2026 alusta hankinta- ja kunnossapitovastuu on rakennuksen omistajalla. Tarkistuslista auttaa havaitsemaan ja ilmoittamaan tarpeen, ei siirrä vastuuta asukkaalle. Sijoitusvaatimukset ja laitekohtaiset ohjeet tarkistat Tukesin sivulta ja valmistajalta.</p>')),
             related=(('/oppaat/kellojen-siirto-2026/', 'Kellojen siirto 25. lokakuuta 2026'), ('/oppaat/talvirenkaat-2026/', 'Talvirenkaat 2026: milloin ne pitää vaihtaa?'), ('/oppaat/#oppaat-sahkokatko-title', 'Kodin varautuminen sähkökatkoon'), ('/categories/kotimaa/', 'Kotimaan uutiset'))),
        dict(path=GUIDE_PATHS[3], title='Liputuspäivät loppuvuonna 2026: isänpäivä 8.11. ja itsenäisyyspäivä 6.12.',
             description='Loka–joulukuun 2026 liputuspäivät päivämäärineen: mitkä ovat virallisia, mitkä vakiintuneita ja mihin aikaan lippu nostetaan ja lasketaan.',
             answer='Loppuvuoden 2026 viralliset liputuspäivät ovat isänpäivä sunnuntaina 8. marraskuuta ja itsenäisyyspäivä sunnuntaina 6. joulukuuta. Vakiintuneita liputuspäiviä ovat 24.10. YK:n päivä, 6.11. ruotsalaisuuden päivä, 20.11. lapsen oikeuksien päivä ja 8.12. Jean Sibeliuksen päivä. Liputus alkaa kello 8 ja päättyy auringon laskiessa; itsenäisyyspäivänä lippu lasketaan kello 20.',
             source=FLAG_SOURCE, source_label='Sisäministeriö: liputuspäivät ja -ajat',
             sections=(
                 ('Liputuspäivät loka–joulukuussa 2026', '<ul><li><strong>La 24.10.</strong> Yhdistyneiden Kansakuntien päivä (vakiintunut liputuspäivä)</li><li><strong>Pe 6.11.</strong> svenska dagen eli ruotsalaisuuden päivä (vakiintunut)</li><li><strong>Su 8.11.</strong> isänpäivä, marraskuun toinen sunnuntai (virallinen liputuspäivä)</li><li><strong>Pe 20.11.</strong> lapsen oikeuksien päivä (vakiintunut)</li><li><strong>Su 6.12.</strong> itsenäisyyspäivä (virallinen liputuspäivä)</li><li><strong>Ti 8.12.</strong> Jean Sibeliuksen päivä eli suomalaisen musiikin päivä (vakiintunut)</li></ul><p>Viikonpäivät on laskettu vuoden 2026 kalenterista. Pyhäinpäivä (lauantai 31.10.2026) ei ole sisäministeriön luettelossa liputuspäivä.</p>'),
                 ('Virallinen vai vakiintunut – mitä ero tarkoittaa?', '<p>Viralliset liputuspäivät on määrätty Suomen lipulla liputtamisesta annetussa asetuksessa, ja niinä päivinä valtion virastot ja laitokset on velvoitettu liputtamaan. Vakiintuneet liputuspäivät on merkitty Helsingin yliopiston toimittamaan Valtiokalenteriin. Sisäministeriön mukaan hyvään liputuskulttuuriin kuuluu liputtaa niinäkin samaan tapaan kuin virallisina päivinä. Yksityishenkilöltä liputusta ei vaadita kumpanakaan päivänä.</p>'),
                 ('Mihin aikaan lippu nostetaan ja lasketaan?', '<ol><li>Nosta lippu aamulla kello 8.</li><li>Laske lippu auringon laskiessa. Loka–joulukuussa aurinko laskee aikaisin, joten tarkista oman paikkakuntasi auringonlaskun aika.</li><li>Itsenäisyyspäivänä 6.12. lippu lasketaan kello 20, vaikka aurinko on laskenut jo aiemmin.</li><li>Kaamosalueilla sisäministeriö on vakiintuneesti suosittanut talvisin liputusta kello 8–16.</li></ol>'),
                 ('Muistilista ennen isänpäivää ja itsenäisyyspäivää', '<p>Tarkista lipun ja salon kunto jo edellisenä päivänä: pimeä aamu ja märkä keli tekevät viime hetken korjauksista hankalia. Taloyhtiössä liputuksesta sopii yleensä isännöitsijä tai hallitus, joten kysy heiltä, jos et tiedä, kuka lipun nostaa. Lipun voi sisäministeriön mukaan nostaa salkoon muulloinkin kuin liputuspäivinä.</p>'),
                 ('Mitä tästä ei voi päätellä?', '<p>Luettelo ei sisällä vaalipäiviä eikä tasavallan presidentin virkaanastumispäivää, jotka ovat myös virallisia liputuspäiviä. Ahvenanmaalla ja saamelaisilla on lisäksi omat liputuspäivänsä omilla lipuillaan. Suruliputuksesta ja valtiovierailujen liputussuosituksista sisäministeriö tiedottaa erikseen.</p>')),
             related=(('/oppaat/kellojen-siirto-2026/', 'Kellojen siirto 25. lokakuuta 2026'), ('/oppaat/talvirenkaat-2026/', 'Talvirenkaat 2026: milloin ne pitää vaihtaa?'), ('/oppaat/palovaroittimen-tarkistus/', 'Palovaroittimen tarkistus pimeän kauden alussa'), ('/categories/kotimaa/', 'Kotimaan uutiset'))),
        dict(path=GUIDE_PATHS[4], title='Influenssarokotus 2026: milloin rokotukset alkavat omalla alueellasi?',
             description='Syksyn 2026 influenssarokotusten alkamispäivät Helsingissä, Vantaalla, Espoossa, Tampereella, Turussa, Oulussa, Jyväskylässä ja Hämeenlinnassa sekä kuka saa rokotteen maksutta.',
             answer='Syksyn 2026 influenssarokotukset alkavat alueittain lokakuussa: Vantaalla ja Keravalla 5.10., Helsingissä 6.10. (alle 75-vuotiaat 19.10.), Varsinais-Suomessa viikolla 43, Länsi-Uudellamaalla muille kuin yli 75-vuotiaille 21.10. ja Keski-Suomessa 24.10. Maksuttoman rokotteen saavat muun muassa kaikki 65 vuotta täyttäneet, alle 7-vuotiaat, raskaana olevat ja riskiryhmiin kuuluvat.',
             source=FLU_SOURCE, source_label='THL: influenssarokote, kansallinen rokotusohjelma',
             sections=(
                 ('Alkamispäivät alueittain', '<ul><li><strong>Helsinki:</strong> terveysasemilla 6.10.–20.11.2026. 75 vuotta täyttäneet 6.10. alkaen, alle 75-vuotiaat kohderyhmäläiset 19.10. alkaen. Aika varataan Maisassa tai kaupungin rokotusajanvarauspuhelimesta. (<a href="https://www.hel.fi/fi/sosiaali-ja-terveyspalvelut/terveydenhoito/terveysasemat/rokotukset/influenssarokotukset" rel="noopener noreferrer">Helsingin kaupunki</a>)</li><li><strong>Vantaa ja Kerava:</strong> rokotukset alkoivat 5.10.2026. Maisan ajanvaraus avautui 8.9. ja puhelinvaraus oman terveysaseman tiimin kautta 29.9. (<a href="https://www.vakehyva.fi/en/seasonal-vaccinations-vantaa-and-kerava-wellbeing-services-county" rel="noopener noreferrer">Vantaan ja Keravan hyvinvointialue</a>)</li><li><strong>Espoo ja muu Länsi-Uusimaa:</strong> yli 75-vuotiaat ja vakavasti immuunipuutteiset 7.10. alkaen. Muut maksuttomaan influenssarokotteeseen oikeutetut: ajanvaraus avautui 7.10., rokotukset alkavat keskiviikkona 21.10.2026. (<a href="https://www.luvn.fi/kausirokotukset-lansi-uudenmaan-hyvinvointialueella" rel="noopener noreferrer">Länsi-Uudenmaan hyvinvointialue</a>)</li><li><strong>Tampere ja Pirkanmaa:</strong> 65 vuotta täyttäneiden ajanvaraus alkaa 13.10., alle 65-vuotiaiden riskiryhmien 20.10. Aika varataan OmaPirhassa tai puhelimitse; lisäksi järjestetään rokotustapahtumia ilman ajanvarausta. (<a href="https://pirha.fi/palvelut/terveyspalvelut/rokotukset/influenssarokotukset" rel="noopener noreferrer">Pirkanmaan hyvinvointialue</a>)</li><li><strong>Turku ja Varsinais-Suomi:</strong> rokotukset alkavat terveysasemilla viikolla 43 eli 19.10. alkavalla viikolla; ajanvaraus avautui 7.10. (<a href="https://www.varha.fi/fi/palvelut/terveysasemapalvelut/influenssa-ja-influenssarokotukset" rel="noopener noreferrer">Varha</a>)</li><li><strong>Oulu ja Pohjois-Pohjanmaa:</strong> rokotukset alkavat lokakuun viimeisellä viikolla ikäryhmittäin vanhimmista alkaen. Ajanvaraus avautui 6.10. ikäryhmittäin OmaPohteessa; puhelinvaraus ma–to klo 8–12 numerossa 08 669 0200. (<a href="https://pohde.fi/ajankohtaista/uutiset/syksyn-2026-influenssa-ja-koronarokotukset-kaynnistyvat-lokakuussa-ikaryhmittain" rel="noopener noreferrer">Pohde</a>)</li><li><strong>Jyväskylä ja Keski-Suomi:</strong> rokotukset alkavat 24.10.2026. Raskaana olevien ja alle 7-vuotiaiden ensimmäinen joukkorokotuspäivä on Palokan neuvolassa lauantaina 24.10. klo 8–15.30. (<a href="https://www.hyvaks.fi/influenssajakoronarokotukset" rel="noopener noreferrer">Keski-Suomen hyvinvointialue</a>)</li><li><strong>Hämeenlinna ja Kanta-Häme:</strong> rokotukset alkavat viikolla 44 (26.10. alkaen), ajanvaraus avautuu viikolla 43. (<a href="https://www.sttinfo.fi/tiedote/72254521/syksyn-2026-influenssa-ja-koronarokotukset-alkavat-oma-hameessa-viikolla-44?publisherId=69820726&lang=fi" rel="noopener noreferrer">Oma Häme</a>)</li><li><strong>Korkeakouluopiskelijat (YTHS):</strong> maksuttoman rokotteen saavat sote-alojen ja riskiryhmiin kuuluvat opiskelijat. Pääkaupunkiseudulla rokotetaan Töölön palvelupisteessä ajanvarauksella 26.10.–6.11.2026. (<a href="https://www.yths.fi/palvelut/tartuntatautien-ehkaisy/rokotukset-yths/influenssarokotukset" rel="noopener noreferrer">YTHS</a>)</li></ul><p>Päivämäärät on koottu hyvinvointialueiden omilta sivuilta 12.10.2026. Alueet päivittävät tietojaan rokotuskauden aikana, joten tarkista oman alueesi sivulta ennen ajan varaamista.</p>'),
                 ('Kuka saa influenssarokotteen maksutta?', '<ul><li>kaikki 65 vuotta täyttäneet</li><li>alle 7-vuotiaat lapset sekä alle 6 kuukauden ikäisten vauvojen kanssa samassa taloudessa asuvat</li><li>raskaana olevat</li><li>sairauden tai hoidon vuoksi riskiryhmiin kuuluvat</li><li>varusmiespalveluksensa tai vapaaehtoisen asepalveluksen aloittavat</li><li>asumisyksiköissä tai laitosmaisissa olosuhteissa pitkäaikaisesti asuvat</li><li>sosiaali- ja terveydenhuollon sekä lääkehuollon henkilöstö</li><li>vakavalle influenssalle erityisen alttiiden henkilöiden lähipiiri</li></ul><p>Ryhmät perustuvat THL:n kansalliseen rokotusohjelmaan, ja hyvinvointialueet tarkistavat oikeuden maksuttomaan rokotteeseen rokotuskäynnillä.</p>'),
                 ('Jos et kuulu maksuttomaan ryhmään', '<p>Rokotteen voi hankkia itse. Hyvinvointialueiden ohjeiden mukaan reseptin voi pyytää omalta terveysasemalta tai digipalvelusta, rokotteen ostaa apteekista ja pistättää terveysasemalla varatulla ajalla. Rokotuksia tarjoavat myös apteekit, yksityiset lääkäriasemat ja monet työterveyshuollot. Aiemman vuoden reseptin voi joillakin alueilla uusia Omakannassa tai apteekissa. Itse ostettua rokotetta on säilytettävä kylmässä ennen rokotusaikaa.</p>'),
                 ('Milloin suoja syntyy ja kuinka kauan se kestää?', '<p>THL:n mukaan suojan syntymiseen menee noin kaksi viikkoa, ja suoja kestää noin vuoden; ikääntyneillä se hiipuu nopeammin. Rokote ei suojaa tavalliselta flunssalta eli nuhakuumeelta. Kauden 2026–2027 rokotteessa kaikki viruskannat on vaihdettu edelliskauteen verrattuna, joten viime syksyn rokotus ei korvaa tämän syksyn rokotusta.</p>'),
                 ('Muistilista rokotuskäynnille', '<ol><li>Tarkista oman alueesi sivulta, onko ajanvaraus jo avautunut sinun ikäryhmällesi. Monella alueella vanhimmat rokotetaan ensin.</li><li>Varaa jokaiselle rokotettavalle oma aika. Toisen aikuisen puolesta voi asioida verkossa vain Suomi.fi-valtuuksilla.</li><li>Jos kuulut myös koronarokotteen kohderyhmään, saat yleensä molemmat samalla käynnillä.</li><li>Pukeudu niin, että olkavarren saa helposti paljaaksi, ja ota Kela-kortti mukaan.</li><li>Jos sinulla on flunssan oireita, siirrä aikaa. Peruuttamattomasta ajasta voidaan periä maksu.</li></ol>')),
             related=(('/oppaat/koronarokotus-2026/', 'Koronarokotus syksyllä 2026: kohderyhmät ja alkamispäivät'), ('/oppaat/kellojen-siirto-2026/', 'Kellojen siirto 25. lokakuuta 2026'), ('/oppaat/talvirenkaat-2026/', 'Talvirenkaat 2026: milloin ne pitää vaihtaa?'), ('/oppaat/liputuspaivat-2026/', 'Liputuspäivät loppuvuonna 2026'), ('/categories/kotimaa/', 'Kotimaan uutiset'))),
        dict(path=GUIDE_PATHS[5], title='Koronarokotus syksyllä 2026: kuka saa rokotteen ja milloin rokotukset alkavat?',
             description='Syksyn 2026 koronarokotusten kohderyhmät ja alkamispäivät Helsingissä, Vantaalla, Espoossa, Tampereella, Oulussa, Jyväskylässä ja Hämeenlinnassa. Kenelle tehosteannos on maksuton ja milloin sitä ei tarvita.',
             answer='Syksyllä 2026 maksuton koronarokotteen tehosteannos annetaan THL:n suosituksen mukaan 75 vuotta täyttäneille, hoivakodeissa ja säännöllisessä kotihoidossa oleville iäkkäille, kaikenikäisille voimakkaasti immuunipuutteisille sekä yli 18-vuotiaille, joilla on vähintään kaksi vakavan koronataudin riskiä lisäävää sairautta. Rokotukset alkavat alueittain 5.–26.10.: Vantaalla 5.10., Helsingissä 6.10. (alle 75-vuotiaat 19.10.), Espoossa 7.10., Keski-Suomessa 24.10. ja Kanta-Hämeessä viikolla 44.',
             source=COVID_SOURCE, source_label='THL: koronarokotteet, ohje ammattilaisille',
             sections=(
                 ('Kuka saa koronarokotteen maksutta syksyllä 2026?', '<p>Hyvinvointialueiden THL:n suositukseen perustuvien ohjeiden mukaan tehosteannosta suositellaan:</p><ul><li>hoivakodeissa tai säännöllisessä kotihoidossa oleville iäkkäille sekä omaishoidettaville iäkkäille</li><li>kaikille 80 vuotta täyttäneille</li><li>kaikenikäisille voimakkaasti immuunipuutteisille</li></ul><p>Tehosteannosta tarjotaan maksutta myös:</p><ul><li>kaikille 75–79-vuotiaille</li><li>yli 18-vuotiaille, joilla on kaksi tai useampi vakavan koronataudin riskiä lisäävä sairaus</li></ul><p>Perusterveille alle 75-vuotiaille aiemmin saatu perussarja antaa hyvän suojan vakavaa tautia vastaan, eikä tehosteannosta heille tarjota. Yksittäistapauksessa lääkäri voi arvioida tarpeen erikseen.</p>'),
                 ('Alkamispäivät alueittain', '<ul><li><strong>Helsinki:</strong> terveysasemilla 6.10.–20.11.2026 vain kohderyhmille. 75 vuotta täyttäneet 6.10. alkaen, alle 75-vuotiaat kohderyhmäläiset 19.10. alkaen. Aika varataan Maisassa tai rokotusajanvarauspuhelimesta 09 310 46300 (ma–pe klo 8–16). Kotihoito rokottaa asiakkaansa loka–marraskuussa. (<a href="https://www.hel.fi/fi/sosiaali-ja-terveyspalvelut/terveydenhoito/terveysasemat/rokotukset/koronarokotukset" rel="noopener noreferrer">Helsingin kaupunki</a>)</li><li><strong>Vantaa ja Kerava:</strong> influenssa- ja koronarokotukset alkoivat 5.10.2026. Maisan ajanvaraus avautui 8.9. ja puhelinvaraus oman terveysaseman tiimin kautta 29.9. (<a href="https://www.vakehyva.fi/en/seasonal-vaccinations-vantaa-and-kerava-wellbeing-services-county" rel="noopener noreferrer">Vantaan ja Keravan hyvinvointialue</a>)</li><li><strong>Espoo, Kauniainen ja muu Länsi-Uusimaa:</strong> yli 75-vuotiaat ja kaikenikäiset vakavasti immuunipuutteiset 7.10. alkaen. Yli 18-vuotiaat, joilla on kaksi tai useampi riskitekijä: ajanvaraus avautui 7.10., rokotukset alkavat keskiviikkona 21.10.2026. Aika varataan Lunnassa tai takaisinsoittopyynnöllä. (<a href="https://www.luvn.fi/kausirokotukset-lansi-uudenmaan-hyvinvointialueella" rel="noopener noreferrer">Länsi-Uudenmaan hyvinvointialue</a>)</li><li><strong>Tampere ja Pirkanmaa:</strong> 75 vuotta täyttäneiden ja voimakkaasti immuunipuutteisten ajanvaraus on käynnissä. 65–74-vuotiaiden riskiryhmien ajanvaraus alkaa 13.10. ja 18–64-vuotiaiden riskiryhmien 20.10.2026. Aika varataan OmaPirhassa tai puhelimitse; lisäksi on rokotustapahtumia ilman ajanvarausta. (<a href="https://pirha.fi/palvelut/terveyspalvelut/rokotukset/koronarokotukset" rel="noopener noreferrer">Pirkanmaan hyvinvointialue</a>)</li><li><strong>Oulu ja Pohjois-Pohjanmaa:</strong> rokotukset alkavat lokakuun viimeisellä viikolla ikäryhmittäin. Ajanvaraus: 80 vuotta tänä vuonna täyttävät ja vanhemmat 6.10. alkaen, 75 vuotta täyttävät 13.10. alkaen ja kaikki muut kohderyhmät 27.10. alkaen. Puhelinvaraus ma–to klo 8–12 numerossa 08 669 0200. (<a href="https://pohde.fi/ajankohtaista/uutiset/syksyn-2026-influenssa-ja-koronarokotukset-kaynnistyvat-lokakuussa-ikaryhmittain" rel="noopener noreferrer">Pohde</a>)</li><li><strong>Jyväskylä ja Keski-Suomi:</strong> rokotukset alkavat lauantaina 24.10.2026 ajanvarauksettomilla joukkorokotuspäivillä 75 vuotta täyttäneille ja 18 vuotta täyttäneille voimakkaasti immuunipuutteisille, esimerkiksi Jyväskylässä Novan sosiaali- ja terveyskeskuksessa (Hoitajantie 3) klo 9–16. Rokotuksia jatketaan 1.12. saakka. (<a href="https://www.hyvaks.fi/influenssajakoronarokotukset" rel="noopener noreferrer">Keski-Suomen hyvinvointialue</a>)</li><li><strong>Hämeenlinna ja Kanta-Häme:</strong> kausirokotukset alkavat viikolla 44 (26.10. alkaen), ajanvaraus avautuu viikolla 43. (<a href="https://www.sttinfo.fi/tiedote/72254521/syksyn-2026-influenssa-ja-koronarokotukset-alkavat-oma-hameessa-viikolla-44?publisherId=69820726&amp;lang=fi" rel="noopener noreferrer">Oma Häme</a>)</li></ul><p>Päivämäärät on koottu hyvinvointialueiden omilta sivuilta 12.10.2026. Alueet päivittävät tietojaan rokotuskauden aikana, joten tarkista oman alueesi sivulta ennen ajan varaamista.</p>'),
                 ('Sairastin koronan äskettäin – tarvitsenko rokotteen?', '<p>Vantaan ja Keravan sekä Pohjois-Pohjanmaan hyvinvointialueiden ohjeiden mukaan loppukesällä (elokuussa) tai syksyllä 2026 koronan sairastanut ei yleensä tarvitse tehosteannosta tämän kauden aikana. Edellisen koronarokotteen ja tehosteannoksen väliin suositellaan vähintään kuutta kuukautta. Lääkäri voi kuitenkin yksilöllisen arvion perusteella suositella rokotetta.</p>'),
                 ('Jos et kuulu maksuttomaan ryhmään', '<p>Koronarokotteen voi ottaa omalla kustannuksellaan. Pohjois-Pohjanmaan hyvinvointialueen ohjeen mukaan resepti pyydetään omasta hyvinvointialueesta, rokote ostetaan apteekista ja pistos annetaan esimerkiksi apteekissa tai sote-keskuksessa. Koronarokotuksia tarjoavat myös yksityiset rokotusklinikat ja lääkäriasemat. Rokotteen saatavuus ja hinta vaihtelevat palveluntarjoajan mukaan.</p>'),
                 ('Muistilista rokotuskäynnille', '<ol><li>Tarkista, kuulutko kohderyhmään, ennen kuin varaat ajan. Helsinki rokottaa terveysasemilla vain kohderyhmiin kuuluvia.</li><li>Jos kuulut myös influenssarokotteen kohderyhmään, saat yleensä molemmat rokotteet samalla käynnillä.</li><li>Varaa jokaiselle rokotettavalle oma aika. Toisen aikuisen puolesta voi asioida verkossa vain Suomi.fi-valtuuksilla.</li><li>Ota mukaan Kela-kortti tai henkilöllisyystodistus ja pukeudu niin, että olkavarren saa helposti paljaaksi.</li><li>Peru aika ajoissa, jos et pääse. Esimerkiksi Länsi-Uudellamaalla peruuttamattomasta ajasta peritään yli 18-vuotiailta 56,70 euroa.</li></ol>')),
             related=(('/oppaat/influenssarokotus-2026/', 'Influenssarokotus 2026: alkamispäivät alueittain'), ('/oppaat/kellojen-siirto-2026/', 'Kellojen siirto 25. lokakuuta 2026'), ('/oppaat/talvirenkaat-2026/', 'Talvirenkaat 2026: milloin ne pitää vaihtaa?'), ('/categories/kotimaa/', 'Kotimaan uutiset'))),
    )


def discovery_html(now):
    return ('<nav class="empty-recovery" aria-label="Käytännön oppaat"><h2>Käytännön oppaat</h2><ul>' +
            ''.join(f'<li><a href="{g["path"]}">{html.escape(g["title"])}</a></li>' for g in guides(now)) + '</ul></nav>')


def render_guide(g, page, public, snapshot=None):
    e = html.escape
    body = ('<article class="story single-article"><header><p>Arjen opas</p>'
            f'<h1>{e(g["title"])}</h1><p class="lead">{e(g["answer"])}</p></header>'
            f'<div class="article-reading-grid"><div class="article-reading-main"><div class="content article-body"><p><a href="{e(g["source"])}" rel="noopener noreferrer">{e(g["source_label"])}</a></p>' +
            ''.join(f'<section><h2>{e(title)}</h2>{text}</section>' for title, text in g['sections']) +
            '<nav aria-label="Aiheeseen liittyvät ohjeet"><h2>Jatka lukemista</h2><ul>' +
            ''.join(f'<li><a href="{e(path)}">{e(label)}</a></li>' for path, label in g['related']) +
            '</ul><p><a href="/oppaat/">Kaikki oppaat</a></p></nav></div></div></div></article>')
    structured = {'@context': 'https://schema.org', '@type': 'WebPage', 'name': g['title'],
                  'url': ORIGIN + g['path'], 'description': g['description'], 'inLanguage': 'fi',
                  'isPartOf': {'@type': 'WebSite', 'url': ORIGIN + '/'},
                  'breadcrumb': {'@type': 'BreadcrumbList', 'itemListElement': [
                      {'@type': 'ListItem', 'position': n, 'name': name, 'item': ORIGIN + path}
                      for n, (name, path) in enumerate((('Etusivu', '/'), ('Oppaat', '/oppaat/'), (g['title'], g['path'])), 1)]}}
    meta = f'<meta name="description" content="{e(g["description"])}"><script type="application/ld+json">' + json.dumps(structured, ensure_ascii=False).replace('<', '\\u003c') + '</script>'
    return page(g['title'], body, g['path'] if public else None, head_meta=meta,
                snapshot=snapshot, active_section='/oppaat/', article_page=True)
